import type { AgentEvent } from "./events";

export interface ToolCall {
	toolUseId: string;
	name: string;
	/** Arguments as generated by the LLM, before the gateway interceptor runs. */
	input: unknown;
	status: "running" | "success" | "error";
	resultText?: string;
	sources: string[];
}

export interface ChatMessage {
	id: string;
	role: "user" | "assistant";
	text: string;
	toolCalls: ToolCall[];
	error?: string;
	pending?: boolean;
}

/** Return the messages after applying one agent event to the last message. */
export function applyEvent(
	messages: ChatMessage[],
	event: AgentEvent,
): ChatMessage[] {
	const last = messages.at(-1);
	if (!last || last.role !== "assistant") {
		return messages;
	}
	return [...messages.slice(0, -1), applyToAssistant(last, event)];
}

function applyToAssistant(
	message: ChatMessage,
	event: AgentEvent,
): ChatMessage {
	switch (event.type) {
		case "text":
			return { ...message, text: message.text + event.data };
		case "tool_use":
			return {
				...message,
				toolCalls: [
					...message.toolCalls,
					{
						toolUseId: event.toolUseId,
						name: event.name,
						input: event.input,
						status: "running",
						sources: [],
					},
				],
			};
		case "tool_result":
			return {
				...message,
				toolCalls: message.toolCalls.map((call) =>
					call.toolUseId === event.toolUseId
						? {
								...call,
								status: event.status,
								resultText: event.text,
								sources: event.sources,
							}
						: call,
				),
			};
		case "error":
			return { ...message, error: event.message };
	}
}

/** Return the userContext.userId that the LLM put in the tool arguments. */
export function requestedUserId(input: unknown): string | undefined {
	if (typeof input !== "object" || input === null) {
		return undefined;
	}
	const userContext = (input as { userContext?: unknown }).userContext;
	if (typeof userContext !== "object" || userContext === null) {
		return undefined;
	}
	const userId = (userContext as { userId?: unknown }).userId;
	return typeof userId === "string" ? userId : undefined;
}

/** Return the file name of an S3 URI. */
export function documentName(uri: string): string {
	return uri.split("/").at(-1) ?? uri;
}
